package com.starlight.greetings.web;
import com.starlight.greetings.application.*; import jakarta.servlet.http.HttpServletRequest; import java.util.*; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/admin") public class AdminModerationController {private final AdminModerationService moderation;private final SessionService sessions;public AdminModerationController(AdminModerationService moderation,SessionService sessions){this.moderation=moderation;this.sessions=sessions;}@GetMapping("/reports") public ApiEnvelope<List<Map<String,Object>>> reports(@RequestHeader(value="x-csrf-token",required=false)String csrf,HttpServletRequest req){sessions.adminRead(SessionCookie.token(req));return ApiEnvelope.of(moderation.reports());}@PostMapping("/letters/{letterId}/review") public ApiEnvelope<Map<String,Object>> review(@PathVariable String letterId,@RequestBody Map<String,String> body,@RequestHeader(value="x-csrf-token",required=false)String csrf,HttpServletRequest req){var user=sessions.admin(SessionCookie.token(req),csrf);return ApiEnvelope.of(moderation.review(letterId,body.get("decision"),body.get("reason"),user.id()));}}
